def count_binary_seq(n):
    if n == 0:
        return 1
    total = 0
    for i in range(2**n):
        ones = sum(int(digit) for digit in bin(i)[2:][:n])
        if ones == sum(int(bin(i)[2:][n:][j]) for j in range(n)):
            total += 1
    return total

